:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #20313a;
  background: #eaf2ee;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 15% 15%, #d4e8dc 0, transparent 42%), #eaf2ee;
}
.card {
  width: min(100%, 700px);
  padding: clamp(24px, 6vw, 48px);
  border: 1px solid #d4e0d8;
  border-radius: 24px;
  background: #fffefa;
  box-shadow: 0 20px 55px #24453818;
}
.eyebrow { margin: 0 0 8px; color: #42755f; font-size: .8rem; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 0; font-size: clamp(2rem, 7vw, 3rem); line-height: 1.1; letter-spacing: -.04em; }
.intro { margin: 12px 0 28px; color: #60736b; }
.grid-wrap { overflow-x: auto; border: 1px solid #dce7df; border-radius: 16px; }
table { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; }
th, td { padding: 10px 6px; text-align: center; }
thead th { height: 48px; color: #668075; font-size: .85rem; font-weight: 700; background: #f2f7f3; }
thead th:first-child, tbody th, tfoot th { width: 86px; }
.sum-heading { width: 76px; }
tbody th { color: #6d8077; font-size: .9rem; font-weight: 700; }
tbody td { border-top: 1px solid #edf1ed; transition: background .16s, box-shadow .16s; }
tbody tr.is-largest td, tbody tr.is-largest th { background: #e2f2e8; }
tbody tr.is-largest th { color: #246344; }
input[type="number"] {
  width: min(100%, 72px);
  height: 48px;
  padding: 0 4px;
  border: 1px solid #d6e2da;
  border-radius: 10px;
  background: #fffefa;
  color: #20313a;
  font: inherit;
  font-size: 1.15rem;
  font-weight: 700;
  text-align: center;
  appearance: textfield;
}
input::-webkit-inner-spin-button, input::-webkit-outer-spin-button { appearance: none; margin: 0; }
input:hover { border-color: #8eb7a0; }
input:focus-visible, button:focus-visible { outline: 3px solid #e7aa53; outline-offset: 2px; }
.row-sum { color: #315d48; font-weight: 800; }
tfoot th, tfoot td { border-top: 1px solid #dce7df; background: #f2f7f3; color: #315d48; font-weight: 800; font-size: .9rem; }
.grand-total { color: #fffefa; background: #315d48; border-radius: 0 0 14px 0; }
.actions { display: flex; align-items: center; gap: 16px; margin-top: 24px; }
button { min-height: 48px; padding: 0 20px; border: 0; border-radius: 12px; background: #315d48; color: #fffefa; font: inherit; font-weight: 750; cursor: pointer; transition: background .15s, transform .1s, box-shadow .15s; }
button:hover { background: #244b39; box-shadow: 0 5px 14px #315d4830; }
button:active { transform: translateY(1px) scale(.98); }
button span { margin-left: 8px; font-size: 1.2rem; }
.status { margin: 0; color: #687b72; font-size: .9rem; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 480px) {
  .card { padding: 24px 16px; border-radius: 20px; }
  th, td { padding: 8px 3px; }
  thead th:first-child, tbody th, tfoot th { width: 68px; }
  .sum-heading { width: 58px; }
  input[type="number"] { height: 44px; font-size: 1rem; }
  .actions { align-items: flex-start; flex-direction: column; gap: 12px; }
}

const body = document.querySelector('#grid-body');

for (let row = 0; row < 4; row += 1) {
  const tr = document.createElement('tr');
  const heading = document.createElement('th');
  heading.scope = 'row';
  heading.textContent = `Row ${row + 1}`;
  tr.append(heading);

  for (let col = 0; col < 4; col += 1) {
    const td = document.createElement('td');
    const input = document.createElement('input');
    input.type = 'number';
    input.min = '1';
    input.max = '9';
    input.step = '1';
    input.value = '1';
    input.setAttribute('aria-label', `Row ${row + 1}, column ${col + 1}`);
    input.addEventListener('input', updateTotals);
    td.append(input);
    tr.append(td);
  }

  const sumCell = document.createElement('td');
  sumCell.className = 'row-sum';
  sumCell.dataset.rowSum = '';
  sumCell.setAttribute('aria-label', `Row ${row + 1} sum`);
  tr.append(sumCell);
  body.append(tr);
}

function cellValue(input) {
  const value = Number(input.value);
  return Number.isInteger(value) && value >= 1 && value <= 9 ? value : 0;
}

function updateTotals() {
  const rows = [...body.rows];
  const columnSums = [0, 0, 0, 0];
  const rowSums = rows.map((row) => {
    const inputs = [...row.querySelectorAll('input')];
    const sum = inputs.reduce((total, input, col) => {
      const value = cellValue(input);
      columnSums[col] += value;
      return total + value;
    }, 0);
    row.querySelector('[data-row-sum]').textContent = sum;
    return sum;
  });

  document.querySelectorAll('[data-col-sum]').forEach((cell, col) => {
    cell.textContent = columnSums[col];
  });
  document.querySelector('#grand-total').textContent = rowSums.reduce((total, sum) => total + sum, 0);

  const largest = Math.max(...rowSums);
  rows.forEach((row, index) => row.classList.toggle('is-largest', rowSums[index] === largest));
}

document.querySelector('#randomize').addEventListener('click', () => {
  body.querySelectorAll('input').forEach((input) => {
    input.value = Math.floor(Math.random() * 9) + 1;
  });
  updateTotals();
});

updateTotals();
